<template><CrudShell title="Quản lý coupon" :loading="loading" :error="error" @create="openCreate" @reload="load"><template #form v-if="editing"><form class="grid gap-3 rounded-3xl border bg-white p-4 md:grid-cols-3" @submit.prevent="save"><input v-model="form.code" class="rounded-xl border p-3" placeholder="Code"><input v-model="form.name" class="rounded-xl border p-3" placeholder="Name"><select v-model="form.discountType" class="rounded-xl border p-3"><option>PERCENT</option><option>FIXED</option></select><input v-model.number="form.discountValue" class="rounded-xl border p-3" placeholder="Discount value"><input v-model.number="form.maxDiscount" class="rounded-xl border p-3" placeholder="Max discount"><input v-model.number="form.minOrderAmount" class="rounded-xl border p-3" placeholder="Min order"><input v-model.number="form.usageLimit" class="rounded-xl border p-3" placeholder="Usage limit"><input v-model="form.startsAt" class="rounded-xl border p-3" placeholder="Starts at"><input v-model="form.endsAt" class="rounded-xl border p-3" placeholder="Ends at"><select v-model="form.status" class="rounded-xl border p-3"><option>ACTIVE</option><option>INACTIVE</option></select><div class="flex gap-2 md:col-span-3"><button class="rounded-xl bg-slate-950 px-4 py-2 font-bold text-white">Save</button><button type="button" class="rounded-xl border px-4 py-2" @click="editing = null">Cancel</button></div></form></template><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-3">Code</th><th>Name</th><th>Type</th><th>Value</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" class="border-b"><td class="p-3 font-bold">{{ row.code }}</td><td>{{ row.name }}</td><td>{{ row.discountType }}</td><td>{{ row.discountValue }}</td><td>{{ row.status }}</td><td class="space-x-2 text-right"><button class="font-bold" @click="openEdit(row)">Edit</button><button class="font-bold text-red-600" @click="remove(row.id)">Delete</button></td></tr></tbody></table></CrudShell></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import CrudShell from '@/pages/admin/CrudShell.vue'; import { couponApi } from '@/modules/promotion/coupon/api'; import { getErrorMessage } from '@/modules/shared/hooks'; import type { Coupon, CouponPayload } from '@/modules/promotion/coupon/types'
const rows = ref<Coupon[]>([]); const loading = ref(false); const error = ref(''); const editing = ref<Coupon | 'new' | null>(null); const form = reactive<CouponPayload>({ code: '', name: '', discountType: 'PERCENT', discountValue: 0, maxDiscount: 0, minOrderAmount: 0, usageLimit: 0, startsAt: '', endsAt: '', status: 'ACTIVE' })
function fill(r?: Coupon) { Object.assign(form, { code: r?.code || '', name: r?.name || '', discountType: r?.discountType || 'PERCENT', discountValue: r?.discountValue || 0, maxDiscount: r?.maxDiscount || 0, minOrderAmount: r?.minOrderAmount || 0, usageLimit: r?.usageLimit || 0, startsAt: r?.startsAt || '', endsAt: r?.endsAt || '', status: r?.status || 'ACTIVE' }) }
function openCreate() { editing.value = 'new'; fill() } function openEdit(r: Coupon) { editing.value = r; fill(r) } async function load() { loading.value = true; try { rows.value = (await couponApi.adminList({ limit: 50 })).items } catch (e) { error.value = getErrorMessage(e) } finally { loading.value = false } } async function save() { try { if (editing.value === 'new') await couponApi.create(form); else if (editing.value) await couponApi.update(editing.value.id, form); editing.value = null; await load() } catch (e) { error.value = getErrorMessage(e) } } async function remove(id: string) { if (!confirm('Delete coupon?')) return; await couponApi.remove(id); await load() } onMounted(load)
</script>
